return msg;

msg.payload = {
    success: true,
    database: 'employees_db',
    result: msg.payload
};
return msg;

msg.payload = {
    success: true,
    database: 'attendance_db',
    result: msg.payload
};
return msg;

const data = msg.payload;

if (!data.employee_id && !data.rfid_uid) {
    msg.error = 'Missing employee_id or rfid_uid';
    return [null, msg];
}

msg.loginData = {
    employee_id: data.employee_id,
    rfid_uid: data.rfid_uid,
    source: data.source || 'rfid'
};

// If we have rfid_uid but no employee_id, we need to look up
if (!data.employee_id && data.rfid_uid) {
    msg.payload = `SELECT id, name, role, rfid_uid, active 
                   FROM employees 
                   WHERE rfid_uid = '${data.rfid_uid}' AND active = true`;
    return [msg, null];
}

// We have employee_id, proceed to check session
msg.payload = `SELECT * FROM active_sessions WHERE employee_id = '${data.employee_id}'`;
return [msg, null];

if (!msg.payload || msg.payload.length === 0) {
    msg.error = 'Employee not found or inactive';
    return [null, msg];
}

const employee = msg.payload[0];
msg.employee = employee;
msg.loginData.employee_id = employee.id;
msg.loginData.rfid_uid = employee.rfid_uid;

// Check if already logged in
msg.payload = `SELECT * FROM active_sessions WHERE employee_id = '${employee.id}'`;
return [msg, null];

if (msg.payload && msg.payload.length > 0) {
    // Already logged in - this is actually a logout request
    msg.isLogout = true;
    msg.session = msg.payload[0];
    return [null, msg];
}

// Not logged in - proceed with login
const data = msg.loginData;
const now = new Date().toISOString();

msg.payload = `
    INSERT INTO active_sessions (employee_id, rfid_uid, login_ts, source)
    VALUES ('${data.employee_id}', '${data.rfid_uid}', '${now}', '${data.source}')
    RETURNING *
`;
return [msg, null];

const session = msg.payload[0];
msg.session = session;

const now = new Date().toISOString();
msg.payload = `
    INSERT INTO attendance_events (employee_id, rfid_uid, event_type, ts, source)
    VALUES ('${session.employee_id}', '${session.rfid_uid}', 'login', '${now}', '${msg.loginData.source}')
`;
return msg;

const employee = msg.employee;
const now = new Date().toISOString();

msg.payload = `
    SELECT * FROM employee_messages 
    WHERE enabled = true 
    AND (valid_from IS NULL OR valid_from <= '${now}')
    AND (valid_to IS NULL OR valid_to >= '${now}')
    AND (
        target_type = 'all'
        OR (target_type = 'employee' AND target_value = '${employee.id}')
        OR (target_type = 'role' AND target_value = '${employee.role}')
    )
    ORDER BY priority DESC, created_at DESC
`;
return msg;

msg.messages = msg.payload || [];

msg.result = {
    success: true,
    type: 'login_success',
    payload: {
        employee: msg.employee,
        session: msg.session,
        messages: msg.messages
    }
};

// Send to WebSocket broadcast
msg.payload = msg.result;
return msg;

const data = msg.payload;

if (!data.employee_id) {
    msg.error = 'Missing employee_id';
    return [null, msg];
}

msg.logoutData = {
    employee_id: data.employee_id,
    source: data.source || 'rfid'
};

// Get session info first
msg.payload = `SELECT * FROM active_sessions WHERE employee_id = '${data.employee_id}'`;
return [msg, null];

if (!msg.payload || msg.payload.length === 0) {
    msg.error = 'Employee not logged in';
    return [null, msg];
}

msg.session = msg.payload[0];

// Delete the session
msg.payload = `DELETE FROM active_sessions WHERE employee_id = '${msg.logoutData.employee_id}'`;
return [msg, null];

const session = msg.session;
const now = new Date().toISOString();

msg.payload = `
    INSERT INTO attendance_events (employee_id, rfid_uid, event_type, ts, source)
    VALUES ('${session.employee_id}', '${session.rfid_uid}', 'logout', '${now}', '${msg.logoutData.source}')
`;
return msg;

const employee = msg.payload[0] || {};

msg.result = {
    success: true,
    type: 'logout_success',
    payload: {
        employee: employee,
        session: msg.session
    }
};

msg.payload = msg.result;
return msg;

msg.payload = {
    success: false,
    type: msg.isLogout ? 'logout_error' : 'login_error',
    payload: {
        error: msg.error || 'Unknown error'
    }
};
return msg;

msg.originalSession = msg._session;
msg.payload = `
    SELECT s.*, e.name, e.role 
    FROM active_sessions s
    JOIN employees e ON e.id = s.employee_id
    ORDER BY s.login_ts DESC
`;
return msg;

msg._session = msg.originalSession;
msg.payload = {
    type: 'full_state',
    payload: {
        activeSessions: msg.payload || [],
        timestamp: new Date().toISOString()
    }
};
return msg;

msg.wsSession = msg._session;
msg.payload = msg.payload.payload;
return msg;

msg.wsSession = msg._session;
msg.payload = msg.payload.payload;
return msg;

msg.broadcastResult = msg.payload;
msg.payload = `
    SELECT s.*, e.name, e.role 
    FROM active_sessions s
    JOIN employees e ON e.id = s.employee_id
    ORDER BY s.login_ts DESC
`;
return msg;

const result = msg.broadcastResult;

// Send the specific result to the requesting client
msg.wsResult = result;

// Create attendance update for all clients
msg.payload = {
    type: 'attendance_update',
    payload: {
        activeSessions: msg.payload || [],
        event: {
            type: result.type,
            employeeId: result.payload?.employee?.id
        },
        timestamp: new Date().toISOString()
    }
};
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization'
};
msg.payload = '';
return msg;

const activeOnly = msg.req.query.active === 'true';
msg.payload = `SELECT id, name, role, rfid_uid, active FROM employees${activeOnly ? ' WHERE active = true' : ''} ORDER BY name`;
return msg;

const id = msg.req.params.id;
msg.payload = `SELECT id, name, role, rfid_uid, active FROM employees WHERE id = '${id}'`;
return msg;

if (!msg.payload || msg.payload.length === 0) {
    msg.statusCode = 404;
    msg.payload = { success: false, error: 'Employee not found' };
} else {
    msg.payload = { success: true, data: msg.payload[0] };
}
return msg;

const uid = msg.req.params.uid;
msg.payload = `SELECT id, name, role, rfid_uid, active FROM employees WHERE rfid_uid = '${uid}'`;
return msg;

if (!msg.payload || msg.payload.length === 0) {
    msg.statusCode = 404;
    msg.payload = { success: false, error: 'Employee not found' };
} else {
    msg.payload = { success: true, data: msg.payload[0] };
}
return msg;

msg.payload = `
    SELECT s.employee_id, s.rfid_uid, s.login_ts, s.source
    FROM active_sessions s
    ORDER BY s.login_ts DESC
`;
return msg;

msg.sessions = msg.payload || [];

if (msg.sessions.length === 0) {
    msg.payload = { success: true, data: { activeSessions: [], employees: [] } };
    return [null, msg];
}

const ids = msg.sessions.map(s => `'${s.employee_id}'`).join(',');
msg.payload = `SELECT id, name, role, rfid_uid FROM employees WHERE id IN (${ids})`;
return [msg, null];

const employees = msg.payload || [];
const sessions = msg.sessions;

// Merge employee info into sessions
const activeSessions = sessions.map(s => {
    const emp = employees.find(e => e.id === s.employee_id) || {};
    return {
        ...s,
        name: emp.name,
        role: emp.role
    };
});

msg.payload = {
    success: true,
    data: {
        activeSessions,
        employees,
        timestamp: new Date().toISOString()
    }
};
return msg;

const id = msg.req.params.id;
msg.payload = `SELECT * FROM active_sessions WHERE employee_id = '${id}'`;
return msg;

msg.payload = {
    success: true,
    data: msg.payload && msg.payload.length > 0 ? msg.payload[0] : null
};
return msg;

const m = msg.payload;
msg.payload = `
    INSERT INTO employee_messages (title, body, target_type, target_value, priority, valid_from, valid_to, enabled)
    VALUES (
        '${m.title}',
        '${m.body || ''}',
        '${m.target_type || 'all'}',
        ${m.target_value ? `'${m.target_value}'` : 'NULL'},
        ${m.priority || 2},
        ${m.valid_from ? `'${m.valid_from}'` : 'NULL'},
        ${m.valid_to ? `'${m.valid_to}'` : 'NULL'},
        ${m.enabled !== false}
    )
    RETURNING *
`;
return msg;

const id = msg.req.params.id;
const m = msg.payload;

const updates = [];
if (m.title) updates.push(`title = '${m.title}'`);
if (m.body !== undefined) updates.push(`body = '${m.body}'`);
if (m.target_type) updates.push(`target_type = '${m.target_type}'`);
if (m.target_value !== undefined) updates.push(`target_value = ${m.target_value ? `'${m.target_value}'` : 'NULL'}`);
if (m.priority) updates.push(`priority = ${m.priority}`);
if (m.valid_from !== undefined) updates.push(`valid_from = ${m.valid_from ? `'${m.valid_from}'` : 'NULL'}`);
if (m.valid_to !== undefined) updates.push(`valid_to = ${m.valid_to ? `'${m.valid_to}'` : 'NULL'}`);
if (m.enabled !== undefined) updates.push(`enabled = ${m.enabled}`);

msg.payload = `UPDATE employee_messages SET ${updates.join(', ')} WHERE id = '${id}' RETURNING *`;
return msg;

if (!msg.payload || msg.payload.length === 0) {
    msg.statusCode = 404;
    msg.payload = { success: false, error: 'Message not found' };
} else {
    msg.payload = { success: true, data: msg.payload[0] };
}
return msg;

const id = msg.req.params.id;
msg.payload = `DELETE FROM employee_messages WHERE id = '${id}'`;
return msg;

msg.employeeId = msg.req.params.id;
msg.payload = `SELECT id, role FROM employees WHERE id = '${msg.employeeId}'`;
return msg;

if (!msg.payload || msg.payload.length === 0) {
    msg.statusCode = 404;
    msg.payload = { success: false, error: 'Employee not found' };
    return [null, msg];
}

