    WHERE enabled = true 
    AND (valid_from IS NULL OR valid_from <= '${now}')
    AND (valid_to IS NULL OR valid_to >= '${now}')
    AND (
        target_type = 'all'
        OR (target_type = 'employee' AND target_value = '${emp.id}')
